"""Static task-shell document. Runtime text is inserted using textContent only.

The shell defaults to reads; installed host authority enables two finite context
commands. Source checks do not establish
rendered accessibility, measured geometry or a working mutation capability.
"""
from __future__ import annotations

import re


def page_bytes(*, nonce: str) -> bytes:
    if type(nonce) is not str or not re.fullmatch(r"[A-Za-z0-9_-]{16,64}", nonce):
        raise ValueError("invalid page nonce")
    page = _PAGE
    # Keep linked recovery in the composer flow.  It is a bounded operator
    # action, not a second page-level overlay; placing it after ``</main>``
    # lets its status text overlap the timeline on narrow/short viewports.
    linked = ('<section id="linked-panel" hidden aria-label="Link a replacement delivery">'
              '<p>Link one replacement delivery for a held context. The parent remains unchanged; '
              'this never retries automatically and keeps uncertain effects visible.</p>'
              '<p id="linked-status" role="status" aria-live="polite"></p>'
              '<div id="linked-actions" class="actions"></div>'
              '<button id="linked-lookup" type="button" hidden>Check outcome</button>'
              '<button id="linked-continue" type="button" hidden>Finish pending link</button></section>')
    page = page.replace(linked, "", 1)
    page = page.replace("</details></footer></section></div></main>",
                        "</details>" + linked + "</footer></section></div></main>", 1)
    page = page.replace('<button id="evidence-open" type="button">Evidence summary</button>',
                        '<div class="actions"><button id="evidence-open" type="button">Evidence summary</button>'
                        '<button id="details-open" type="button">Reviews and decisions</button></div>', 1)
    detail_markup = ('<aside id="details-drawer" class="drawer" role="dialog" aria-modal="true" '
                     'aria-labelledby="details-title" hidden><header><h2 id="details-title">Reviews and decisions</h2>'
                     '<button id="details-close" type="button">Close</button></header>'
                     '<p id="details-status" role="status" aria-live="polite"></p>'
                     '<div id="details-list"></div><div id="details-body"></div></aside>')
    detail_script = ('const detailEl=id=>document.getElementById(id);let detailFocus=null,detailGeneration=0;'
                      'function focusIfVisible(target,fallback){const candidate=target&&target.isConnected&&!target.hidden&&!target.closest("[hidden]")?target:fallback;if(candidate&&!candidate.hidden&&!candidate.closest("[hidden]"))candidate.focus({preventScroll:true})}'
                      'function clearPrivilegedOverlays(){detailGeneration++;detailEl("details-drawer").hidden=true;detailEl("details-list").replaceChildren();detailEl("details-body").replaceChildren();detailFocus=null;el("drawer").hidden=true;el("evidence-body").replaceChildren();drawerFocus=null;el("scrim").hidden=true;el("app").inert=false}'
                      'function closeDetails(){detailGeneration++;detailEl("details-drawer").hidden=true;detailEl("details-list").replaceChildren();detailEl("details-body").replaceChildren();if(el("drawer").hidden){el("scrim").hidden=true;el("app").inert=false}const opener=detailFocus&&detailFocus.isConnected?detailFocus:null;detailFocus=null;focusIfVisible(opener,detailEl("details-open"))}'
                     'function closeActiveOverlay(){if(!detailEl("details-drawer").hidden)return closeDetails();if(!el("drawer").hidden)return closeDrawer()}'
                     'function detailQuery(item){const q=new URLSearchParams({target:item.id,source:item.source_kind,task:item.task_id});return "/api/details?"+q}'
                     'function detailField(label,value){if(value===undefined||value===null||value==="")return null;const p=node("p");p.append(node("strong",label+": "),node("span",String(value)));return p}'
                      'function detailButton(item){const b=node("button",item.label+" / "+item.source_kind.replaceAll("_"," "));b.type="button";b.addEventListener("click",async()=>{const generation=++detailGeneration;detailEl("details-status").textContent="Loading detail…";try{const d=await request(detailQuery(item));if(generation!==detailGeneration||!bearer||detailEl("details-drawer").hidden)return;const bodyEl=detailEl("details-body");const parts=[node("h3",d.title),node("p",d.summary||"Metadata only"),node("p","Type: "+d.source_kind+" / state: "+d.state)];for(const field of [["Disposition",d.disposition],["Next decision",d.next_decision],["Decision",d.decision]]){const p=detailField(field[0],field[1]);if(p)parts.push(p)}if(Array.isArray(d.criteria)&&d.criteria.length){const list=node("ul");for(const criterion of d.criteria){const label=criterion&&criterion.label!==undefined?criterion.label:"criterion";const result=criterion&&criterion.result!==undefined?criterion.result:"unknown";list.append(node("li",String(label)+": "+String(result)))}parts.push(node("h4","Criteria"),list)}bodyEl.replaceChildren(...parts);if(item.body_available){const body=node("button","Open separately authorized body");body.type="button";body.addEventListener("click",async()=>{if(body.disabled)return;const bodyGeneration=generation;if(document.activeElement===body)detailEl("details-close").focus({preventScroll:true});body.disabled=true;detailEl("details-status").textContent="Loading authorized body…";try{const text=await request("/api/details/body",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({target:item.id,source:item.source_kind,task:item.task_id})});if(bodyGeneration!==detailGeneration||!bearer||detailEl("details-drawer").hidden)return;if(!bodyEl.querySelector("pre[data-detail-body]")){const pre=node("pre",text.body);pre.dataset.detailBody="true";bodyEl.append(pre)}body.textContent="Authorized body loaded";detailEl("details-status").textContent="Typed detail loaded; raw receipts and private references remain excluded."}catch(error){if(bodyGeneration!==detailGeneration||!bearer||detailEl("details-drawer").hidden)return;body.disabled=false;detailEl("details-status").textContent="Body scope unavailable: "+error.message}});bodyEl.append(body)}detailEl("details-status").textContent="Typed detail loaded; raw receipts and private references remain excluded."}catch(error){if(generation!==detailGeneration||!bearer||detailEl("details-drawer").hidden)return;detailEl("details-status").textContent="Detail unavailable: "+error.message}});return b}'
                      'async function openDetails(){detailGeneration++;detailFocus=document.activeElement;detailEl("details-drawer").hidden=false;detailEl("scrim").hidden=false;el("app").inert=true;detailEl("details-close").focus({preventScroll:true});detailEl("details-list").replaceChildren();detailEl("details-body").replaceChildren();const cap=current?.details;if(!cap?.available){detailEl("details-status").textContent=cap?.reason||"Detail scope unavailable.";return}const targets=cap.targets.filter(item=>!current.selected_task_id||item.task_id===current.selected_task_id);detailEl("details-status").textContent=targets.length?"Select a typed review or decision.":"No typed reviews or decisions are available for the focused task.";for(const item of targets)detailEl("details-list").append(detailButton(item))}'
                     'detailEl("details-open").addEventListener("click",openDetails);detailEl("details-close").addEventListener("click",closeDetails);'
                     'detailEl("details-drawer").addEventListener("keydown",event=>{if(event.key==="Escape"){event.preventDefault();closeDetails();return}if(event.key!=="Tab")return;const drawer=detailEl("details-drawer"),items=Array.from(drawer.querySelectorAll("button,[href],input,select,textarea,[tabindex]")).filter(item=>!item.disabled&&!item.hidden&&!item.closest("[hidden]")&&item.getAttribute("aria-hidden")!=="true");if(!items.length){event.preventDefault();detailEl("details-close").focus({preventScroll:true});return}const first=items[0],last=items[items.length-1],active=document.activeElement;if(event.shiftKey&&(active===first||!items.includes(active))){event.preventDefault();last.focus({preventScroll:true})}else if(!event.shiftKey&&(active===last||!items.includes(active))){event.preventDefault();first.focus({preventScroll:true})}});')
    script_marker = '<' + 'script nonce="__NONCE__">'
    page = page.replace(script_marker, detail_markup + script_marker, 1)
    page = page.replace('</script></body></html>', detail_script +
                        '</script></body></html>', 1)
    page = page.replace("#command-panel{min-height:3.5rem;max-height:7rem;overflow:auto}.composer p{",
                        "#command-panel{min-height:3.5rem;max-height:7rem;overflow:auto}"
                        "#details-body pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;overflow:auto}"
                        "#linked-panel{border-top:1px solid var(--line);margin-top:.6rem;padding-top:.6rem}.composer p{", 1)
    page = page.replace("el('skip').hidden=true;el('drawer').hidden=true;el('scrim').hidden=true;el('app').inert=false;drawerFocus=null;",
                        "el('skip').hidden=true;clearPrivilegedOverlays();", 1)
    page = page.replace("completePending(data);completePendingMessage(data);completePendingDisposition(data);",
                        "completePending(data);completePendingMessage(data);completePendingDisposition(data);completePendingLinked(data);", 1)
    page = page.replace("function closeDrawer(){el('drawer').hidden=true;el('scrim').hidden=true;el('app').inert=false;if(drawerFocus)drawerFocus.focus()}",
                        "function closeDrawer(){el('drawer').hidden=true;if(detailEl('details-drawer').hidden){el('scrim').hidden=true;el('app').inert=false}const opener=drawerFocus;drawerFocus=null;focusIfVisible(opener,el('evidence-open'))}", 1)
    page = page.replace("el('scrim').addEventListener('click',closeDrawer)",
                        "el('scrim').addEventListener('click',closeActiveOverlay)", 1)
    return page.replace("__NONCE__", nonce).encode("utf-8")


